using System;using System.IO;using UCSPyayStudentRegistration.Models;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Tests { public static class WorkflowSelfTest { public static void Run(){string file=Path.GetTempFileName();try{File.WriteAllText(file,"demo");string msg;if(!new AdmissionQuery().CheckAdmission("PYAY-2026-001",out msg))throw new Exception("First Year admission check failed: "+msg);Submit(1,"PYAY-2026-001",null,file,"Test First Year "+DateTime.Now.Ticks);if(!new ResultQuery().CheckExisting("PaKaPaTa-002198",out msg))throw new Exception("Existing student result check failed: "+msg);Submit(2,"PaKaPaTa-002198","PaKaPaTa-002198",file,"Maung Maung");}finally{try{File.Delete(file);}catch{}}}static void Submit(int year,string proof,string roll,string file,string name){var d=new WizardData();d.SeatOrRoll=proof;d.Student.StudentName=name;d.Student.Gender="Male";d.Student.DateOfBirth=new DateTime(2005,1,1);d.Student.Nrc="7/PaMaNa(N)123456";d.Student.Phone="09123456789";d.Student.Email="test@example.com";d.Student.Address="Pyay";d.Student.Major="Computer Science";d.Student.Year=year;d.Student.AcademicYear="2026-2027";d.Student.UniversityRollNo=roll;d.Parent.FatherName="Demo Father";d.Parent.MotherName="Demo Mother";d.Documents.Add(new RegistrationDocument{DocumentType="Workflow Test",FileName="test.tmp",FilePath=file,FileSize=4});d.Payment.RequiredAmount=30000;d.Payment.PaidAmount=30000;d.Payment.Method="Mobile Payment";d.Payment.TransactionId="TEST-"+Guid.NewGuid().ToString("N");d.Payment.PaymentDate=DateTime.Today;d.Payment.ReceiptPath=file;string no=new ApplicationQuery().Submit(d);if(string.IsNullOrWhiteSpace(no)||!no.StartsWith("APP-"))throw new Exception("Application number was not generated.");}}
}
